#include <atspi/atspi.h>
#include <json-glib/json-glib.h>
#include <glib.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INPUT_BYTES 64000
#define MAX_TRAVERSAL 10000

typedef struct { const gchar *app_id; const gchar *window_id; const gchar *control_id; const gchar *expected; } Request;

static const gchar *str_member(JsonObject *o,const gchar *name){return json_object_has_member(o,name)?json_object_get_string_member(o,name):NULL;}
static gboolean valid_id(const gchar *s){if(!s||!*s||strlen(s)>512)return FALSE;for(const gchar *p=s;*p;p++)if(*p=='\r'||*p=='\n')return FALSE;return TRUE;}
static gboolean lower_hex64(const gchar *s){if(!s||strlen(s)!=64)return FALSE;for(const gchar *p=s;*p;p++)if(!((*p>='0'&&*p<='9')||(*p>='a'&&*p<='f')))return FALSE;return TRUE;}
static gchar *read_stdin(void){GByteArray *a=g_byte_array_new();guint8 b[4096];while(!feof(stdin)){size_t n=fread(b,1,sizeof b,stdin);if(n){if(a->len+n>MAX_INPUT_BYTES){g_byte_array_unref(a);return NULL;}g_byte_array_append(a,b,n);}if(ferror(stdin)){g_byte_array_unref(a);return NULL;}}g_byte_array_append(a,(const guint8*)"\0",1);return (gchar*)g_byte_array_free(a,FALSE);}
static gchar *process_image(guint pid){gchar *link=g_strdup_printf("/proc/%u/exe",pid),buf[4096];ssize_t n=readlink(link,buf,sizeof(buf)-1);g_free(link);if(n<=0)return NULL;buf[n]='\0';return g_canonicalize_filename(buf,NULL);}
static gchar *accessible_id(AtspiAccessible *a){GError *e=NULL;gchar *id=atspi_accessible_get_accessible_id(a,&e);if(e){g_error_free(e);g_free(id);return NULL;}return id;}
static gchar *name_of(AtspiAccessible *a){GError *e=NULL;gchar *s=atspi_accessible_get_name(a,&e);if(e){g_error_free(e);g_free(s);return g_strdup("");}return s?s:g_strdup("");}
static gchar *role_of(AtspiAccessible *a){GError *e=NULL;gchar *s=atspi_accessible_get_role_name(a,&e);if(e){g_error_free(e);g_free(s);return g_strdup("");}return s?s:g_strdup("");}
static gboolean state_has(AtspiAccessible *a,AtspiStateType state){AtspiStateSet *set=atspi_accessible_get_state_set(a);if(!set)return FALSE;gboolean v=atspi_state_set_contains(set,state);g_object_unref(set);return v;}
static gint child_count(AtspiAccessible *a){GError *e=NULL;gint n=atspi_accessible_get_child_count(a,&e);if(e){g_error_free(e);return -1;}return n;}
static AtspiAccessible *child_at(AtspiAccessible *a,gint i){GError *e=NULL;AtspiAccessible *c=atspi_accessible_get_child_at_index(a,i,&e);if(e){g_error_free(e);if(c)g_object_unref(c);return NULL;}return c;}

static AtspiAccessible *find_app(const gchar *app_id){AtspiAccessible *desktop=atspi_get_desktop(0);if(!desktop)return NULL;AtspiAccessible *match=NULL;gint matches=0,n=child_count(desktop);for(gint i=0;i<n;i++){AtspiAccessible *app=child_at(desktop,i);if(!app)continue;GError *e=NULL;guint pid=atspi_accessible_get_process_id(app,&e);if(e){g_error_free(e);g_object_unref(app);continue;}gchar *image=process_image(pid);if(image&&g_strcmp0(image,app_id)==0){matches++;if(!match)match=g_object_ref(app);}g_free(image);g_object_unref(app);}g_object_unref(desktop);if(matches!=1){if(match)g_object_unref(match);return NULL;}return match;}
static AtspiAccessible *find_window(AtspiAccessible *app,const gchar *window_id){AtspiAccessible *match=NULL;gint matches=0,n=child_count(app);for(gint i=0;i<n;i++){AtspiAccessible *w=child_at(app,i);if(!w)continue;gchar *id=accessible_id(w);if(id&&g_strcmp0(id,window_id)==0){matches++;if(!match)match=g_object_ref(w);}g_free(id);g_object_unref(w);}if(matches!=1){if(match)g_object_unref(match);return NULL;}return match;}
static AtspiAccessible *find_control(AtspiAccessible *window,const gchar *control_id){GQueue q=G_QUEUE_INIT;gint n=child_count(window);for(gint i=0;i<n;i++){AtspiAccessible *c=child_at(window,i);if(c)g_queue_push_tail(&q,c);}AtspiAccessible *match=NULL;gint matches=0,seen=0;while(!g_queue_is_empty(&q)){AtspiAccessible *a=g_queue_pop_head(&q);if(++seen>MAX_TRAVERSAL){g_object_unref(a);break;}gchar *id=accessible_id(a);if(id&&g_strcmp0(id,control_id)==0){matches++;if(!match)match=g_object_ref(a);}g_free(id);gint m=child_count(a);for(gint j=0;j<m&&seen+(gint)g_queue_get_length(&q)<MAX_TRAVERSAL;j++){AtspiAccessible *c=child_at(a,j);if(c)g_queue_push_tail(&q,c);}g_object_unref(a);}while(!g_queue_is_empty(&q))g_object_unref(g_queue_pop_head(&q));if(matches!=1){if(match)g_object_unref(match);return NULL;}return match;}

static gchar *state_digest(const Request *r,AtspiAccessible *window,AtspiAccessible *control){gchar *wid=accessible_id(window),*wname=name_of(window),*cid=accessible_id(control),*cname=name_of(control),*role=role_of(control);AtspiAction *action=atspi_accessible_get_action_iface(control);gchar *action0=NULL;if(action){GError *e=NULL;if(atspi_action_get_n_actions(action,&e)>0&&!e)action0=atspi_action_get_action_name(action,0,&e);if(e)g_error_free(e);g_object_unref(action);}gchar *material=g_strdup_printf("CIEAV_DESKTOP_UI_STATE_V1\n%s\n%s\n%s\n%s\n%s\n%s\nenabled=%d\nfocused=%d\nshowing=%d\ndefault-action=%s",r->app_id,wid?wid:"",wname,cid?cid:"",cname,role,state_has(control,ATSPI_STATE_ENABLED)?1:0,state_has(control,ATSPI_STATE_FOCUSED)?1:0,state_has(control,ATSPI_STATE_SHOWING)?1:0,action0?action0:"");GChecksum *sum=g_checksum_new(G_CHECKSUM_SHA256);g_checksum_update(sum,(const guchar*)material,strlen(material));gchar *out=g_strdup(g_checksum_get_string(sum));g_checksum_free(sum);g_free(material);g_free(wid);g_free(wname);g_free(cid);g_free(cname);g_free(role);g_free(action0);return out;}
static void emit(gboolean started,const gchar *transport,const gchar *detail,const gchar *post){if(post)g_print("{\"version\":1,\"kind\":\"EXECUTION_RESULT\",\"effectStarted\":%s,\"transport\":\"%s\",\"detailCode\":\"%s\",\"postStateDigest\":\"%s\"}\n",started?"true":"false",transport,detail,post);else g_print("{\"version\":1,\"kind\":\"EXECUTION_RESULT\",\"effectStarted\":%s,\"transport\":\"%s\",\"detailCode\":\"%s\"}\n",started?"true":"false",transport,detail);}

int main(void){gchar *raw=read_stdin();if(!raw)return 2;JsonParser *p=json_parser_new();GError *e=NULL;if(!json_parser_load_from_data(p,raw,-1,&e)){if(e)g_error_free(e);g_free(raw);g_object_unref(p);return 2;}g_free(raw);JsonNode *root=json_parser_get_root(p);if(!root||!JSON_NODE_HOLDS_OBJECT(root)){g_object_unref(p);return 2;}JsonObject *o=json_node_get_object(root);const gchar *kind=str_member(o,"kind"),*platform=str_member(o,"platform"),*action_name=str_member(o,"action"),*ticket=str_member(o,"ticketId"),*proposal=str_member(o,"proposalId"),*args_digest=str_member(o,"normalizedArgumentsDigest"),*app_id=str_member(o,"appId"),*window_id=str_member(o,"windowId"),*control_id=str_member(o,"controlId"),*expected=str_member(o,"expectedStateDigest");if(!json_object_has_member(o,"version")||json_object_get_int_member(o,"version")!=1||g_strcmp0(kind,"INVOKE")||g_strcmp0(platform,"linux")||g_strcmp0(action_name,"INVOKE")||!ticket||!g_uuid_string_is_valid(ticket)||!proposal||!g_uuid_string_is_valid(proposal)||!lower_hex64(args_digest)||!lower_hex64(expected)||!valid_id(app_id)||!valid_id(window_id)||!valid_id(control_id)){g_object_unref(p);return 2;}if(atspi_init()!=0){g_object_unref(p);return 3;}Request r={app_id,window_id,control_id,expected};AtspiAccessible *app=find_app(app_id),*window=app?find_window(app,window_id):NULL,*control=window?find_control(window,control_id):NULL;if(!app||!window||!control){emit(FALSE,"REJECTED","TARGET_NOT_EXACT",NULL);goto done;}gchar *before=state_digest(&r,window,control);if(g_strcmp0(before,expected)){g_free(before);emit(FALSE,"REJECTED","PRESTATE_MISMATCH",NULL);goto done;}g_free(before);if(!state_has(control,ATSPI_STATE_ENABLED)||!state_has(control,ATSPI_STATE_SHOWING)){emit(FALSE,"REJECTED","CONTROL_NOT_INVOKABLE_STATE",NULL);goto done;}AtspiAction *action=atspi_accessible_get_action_iface(control);if(!action){emit(FALSE,"REJECTED","DEFAULT_ACTION_UNAVAILABLE",NULL);goto done;}GError *action_error=NULL;gint count=atspi_action_get_n_actions(action,&action_error);if(action_error||count<1){if(action_error)g_error_free(action_error);g_object_unref(action);emit(FALSE,"REJECTED","DEFAULT_ACTION_UNAVAILABLE",NULL);goto done;}gboolean ok=atspi_action_do_action(action,0,&action_error);g_object_unref(action);if(!ok||action_error){if(action_error)g_error_free(action_error);emit(TRUE,"UNKNOWN","DEFAULT_ACTION_FAILED",NULL);goto done;}AtspiAccessible *post_app=find_app(app_id),*post_window=post_app?find_window(post_app,window_id):NULL,*post_control=post_window?find_control(post_window,control_id):NULL;gchar *post=NULL;if(post_app&&post_window&&post_control)post=state_digest(&r,post_window,post_control);emit(TRUE,"ACCEPTED","DEFAULT_ACTION_DISPATCHED",post);g_free(post);if(post_control)g_object_unref(post_control);if(post_window)g_object_unref(post_window);if(post_app)g_object_unref(post_app);
done:if(control)g_object_unref(control);if(window)g_object_unref(window);if(app)g_object_unref(app);atspi_exit();g_object_unref(p);return 0;}
